const readiness=()=>{if(!state.assets.length)return 0;const described=state.assets.filter(item=>item.note?.trim()).length,attached=new Set(state.attachments.map(item=>item.assetId)).size;return Math.round((state.assets.length*45+described*35+attached*20)/state.assets.length);};
