function bindOverlay(){overlay.querySelectorAll('[data-close]').forEach(el=>el.onclick=event=>{if(event.target===el||el.classList.contains('modal-close'))overlay.innerHTML='';});}
function videoModal(){overlay.innerHTML=`<div class="modal-backdrop" data-close><section class="modal" role="dialog" aria-modal="true" aria-labelledby="video-title"><button class="modal-close" data-close aria-label="关闭">×</button><div class="video-poster"><div class="play">▶</div></div><h2 id="video-title">60秒了解${brand.brand_name}</h2><p>正式介绍视频正在制作。本入口为明确的Placeholder，不会播放伪造内容。</p></section></div>`;bindOverlay();overlay.querySelector('.modal-close').focus();}
function helpDrawer(){overlay.innerHTML=`<div class="drawer-backdrop" data-close><aside class="help-drawer" role="dialog" aria-modal="true" aria-labelledby="help-title"><button class="modal-close" data-close aria-label="关闭">×</button><p class="kicker">CONTEXTUAL HELP</p><h2 id="help-title">如何填写恢复线索</h2><h3>建议记录</h3><p>官方恢复入口、资料保管位置、所需设备、可信联系人和停止条件。</p><h3>不要记录</h3><p>私钥、助记词、OTP、Authenticator Seed、完整密码或验证码。</p><h3>为什么</h3><p>Recovery Map帮助恢复人知道从哪里开始，但不应成为秘密仓库。</p><div class="video-mini"><span>60秒教程</span><b>Coming soon</b></div></aside></div>`;bindOverlay();overlay.querySelector('.modal-close').focus();}

async function localEncrypt(){let password=document.querySelector('#password').value,confirmation=document.querySelector('#password-confirm').value,button=document.querySelector('[data-local-encrypt]');try{button.disabled=true;button.textContent='正在本地加密…';const policy=await fetch('../../config/security/recovery-password-v1.json',{cache:'no-store'}).then(r=>r.json()),check=validateRecoveryPassword(password,confirmation,document.querySelector('#ack').checked,{policy,vaultName:'LEGAVIK Recovery Map'});if(!check.valid)throw new Error(check.issues[0].message);state.artifacts=await createCryptoProductArtifacts({assets:state.assets,attachments:state.attachments,password});document.querySelector('#create-steps').children[0].className='done';document.querySelector('#create-steps').children[1].className='done';document.querySelector('.progress span').className='progress-local-complete';document.querySelector('#create-status').textContent='本地保护已完成；正式永久存储尚未执行。';document.querySelector('#password-card').classList.add('hidden');const card=document.querySelector('#materials-card');card.classList.remove('hidden');card.innerHTML=`<div class="success-state"><span>✓</span><h2>本地体验版本已创建</h2><p>请保存Recovery Kit。本轮不会执行付款或Mainnet广播，因此不会生成Mainnet Recovery Evidence。</p><button class="button" data-save-kit>保存Recovery Kit</button><button class="button secondary" data-save-backup>保存本地加密备份（可选）</button><button class="text-link" data-route="independent-recovery">进入独立恢复入口</button></div>`;bind();announce('本地加密完成');}catch(error){announce(error.message);button.disabled=false;button.textContent='创建本地体验版本';}finally{password='';confirmation='';const p=document.querySelector('#password'),c=document.querySelector('#password-confirm');if(p)p.value='';if(c)c.value='';}}

async function addFiles(input){try{const existing=state.attachments.map(item=>({file:{name:item.name,size:item.bytes.length}})),added=await validateIncomingFiles(input.files,existing);for(const item of added)state.attachments.push({id:uid(),assetId:input.dataset.files,name:item.identity.filename,mimeType:item.identity.mimeType,bytes:item.bytes});if(totalBytes()>UNIFIED_LIMITS.max_total_original_bytes)throw new Error('累计附件容量不得超过50 MiB');render();announce(`已添加${added.length}个文件`);}catch(error){announce(error.message);}}

function bind(){document.querySelectorAll('[data-route]').forEach(el=>el.onclick=()=>{const target=el.dataset.route;if(target==='independent-recovery')location.href=canonicalRecoveryUrl('recovery-center');else if(['map','preview'].includes(target))location.href=canonicalCreateUrl();else navigate(target);});document.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{state.category=state.category===el.dataset.category?null:el.dataset.category;persist();render();announce(state.category?`${category(state.category).zh} 已选择`:'已取消选择');});document.querySelectorAll('[data-brand]').forEach(el=>el.onclick=()=>{const match=state.assets.find(a=>a.category===state.category&&a.name===el.dataset.brand);if(match)state.assets=state.assets.filter(a=>a.id!==match.id);else state.assets.push({id:uid(),category:state.category,name:el.dataset.brand,note:''});persist();render();announce(match?`${el.dataset.brand} 已取消`:`${el.dataset.brand} 已选择`);});document.querySelector('[data-custom]')?.addEventListener('click',()=>document.querySelector('#custom').classList.remove('hidden'));document.querySelector('[data-add-custom]')?.addEventListener('click',()=>{const value=document.querySelector('#custom-name').value.trim();if(!value)return announce('请输入项目名称');state.assets.push({id:uid(),category:state.category,name:value,note:''});persist();render();announce(`${value} 已添加`);});document.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{const asset=state.assets.find(a=>a.id===el.dataset.note);asset.note=el.value;persist();});document.querySelectorAll('[data-files]').forEach(el=>el.onchange=()=>addFiles(el));document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{state.assets=state.assets.filter(a=>a.id!==el.dataset.remove);state.attachments=state.attachments.filter(f=>f.assetId!==el.dataset.remove);persist();render();announce('资产项目已移除');});document.querySelectorAll('[data-video]').forEach(el=>el.onclick=videoModal);document.querySelectorAll('[data-help]').forEach(el=>el.onclick=helpDrawer);document.querySelectorAll('[data-close]').forEach(el=>el.onclick=e=>{if(e.target===el||el.classList.contains('modal-close'))overlay.innerHTML='';});document.querySelector('[data-demo-payment]')?.addEventListener('click',()=>{document.querySelector('.payment-card').classList.add('muted-card');document.querySelector('#password-card').classList.remove('hidden');document.querySelector('#password-card input').focus();announce('Payment Gate体验通过，未产生付款');});document.querySelector('[data-local-encrypt]')?.addEventListener('click',localEncrypt);document.querySelector('[data-save-kit]')?.addEventListener('click',async()=>{const r=await saveMaterial({bytes:state.artifacts.kitBytes,filename:`Recovery-Kit-LEGAVIK-${state.artifacts.snapshotId}.cjas`,mimeType:'application/octet-stream'});state.kitSaved=r.saved;if(r.saved)announce('Recovery Kit已保存');});document.querySelector('[data-save-backup]')?.addEventListener('click',async()=>{await saveMaterial({bytes:state.artifacts.archiveBytes,filename:`Local-Encrypted-Backup-LEGAVIK-${state.artifacts.snapshotId}.cjasvault`,mimeType:'application/octet-stream'});announce('本地加密备份已保存');});document.querySelector('#register-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);state.account={name:data.get('name'),email:data.get('email')};persist();announce('体验账户已保存');setTimeout(()=>navigate('control'),500);});document.querySelector('#menu')?.addEventListener('click',e=>{const open=header.classList.toggle('menu-open');e.currentTarget.setAttribute('aria-expanded',String(open));});}

function bindSaveFeedback(){const targets=[];const assetContinue=document.querySelector('.sticky-actions .button');if(assetContinue)targets.push(assetContinue);const mapContinue=document.querySelector('.map-layout .actions .button:not(.secondary)');if(mapContinue)targets.push(mapContinue);for(const button of targets){const destination=state.route==='digital-assets'?'map':'preview';button.onclick=()=>{if(button.disabled)return;button.disabled=true;button.textContent='正在保存…';persist();announce('已保存，正在进入下一步');setTimeout(()=>navigate(destination),180);};}}
function bindProductIntegration(){document.querySelectorAll('[data-recovery-map]').forEach(el=>el.onclick=()=>{location.href=canonicalCreateUrl();});document.querySelectorAll('[data-independent-recovery]').forEach(el=>el.onclick=()=>{location.href=canonicalRecoveryUrl('recovery-center');});document.querySelectorAll('[data-route="digital-assets"]').forEach(el=>el.onclick=()=>navigate('digital-assets'));}
function render(){state.route=route();document.documentElement.classList.toggle('knowledge-route',state.route==='knowledge');persist();nav();foot();if(state.route==='home')home();else if(state.route==='digital-assets')digitalAssetsGuide();else if(state.route==='security')securityPrivacyGuide();else if(state.route==='pricing')pricingPage();else if(state.route==='knowledge')knowledgeBasePage();else if(state.route==='professionals')professionalsPage();else if(state.route==='about')aboutPage();else if(state.route==='control')control();else if(state.route==='register')register();else if(['recovery','how-it-works','help'].includes(state.route))simplePage(state.route);else home();bind();bindProductIntegration();bindSaveFeedback();main.focus({preventScroll:true});scrollTo({top:0,behavior:'auto'});}
addEventListener('hashchange',render);addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay.innerHTML)overlay.innerHTML='';});render();
addEventListener('pageshow',()=>{if(!main.children.length)render();});
